                {readonly ? (
                  <span className={`pill ${CONV[p.conv_state].cls}`}>
                    {CONV[p.conv_state].label}
                  </span>
                ) : p.conv_state === 'done' ? (
                  <span className="meta" style={{ color: 'var(--st-read)' }}>
                    已生成 · {relTime(p.status_at || p.created_at)}
                  </span>
                ) : p.conv_state === 'failed' ? (
                  <button className="chip danger" disabled={busy === p.id}
